package audit

import (
	"regexp"
	"sort"
	"strings"
)

type LanguageSignal struct {
	Language   string
	Confidence float64
	Evidence   string
}

var codeFenceRE = regexp.MustCompile("(?is)```\\s*([a-zA-Z0-9_+#.-]+)?\\s*\\n(.*?)```")
var filenameRE = regexp.MustCompile(`(?i)\b[\w./-]+\.(py|js|jsx|ts|tsx|go|rs|java|kt|kts|cs|cpp|cc|cxx|c|h|hpp|rb|php|swift|sql|yaml|yml|json|toml|sh|bash|ps1|dockerfile|gradle|scala)\b`)

var fenceLanguageMap = map[string]string{
	"py":         "Python",
	"python":     "Python",
	"js":         "JavaScript",
	"javascript": "JavaScript",
	"jsx":        "JavaScript",
	"ts":         "TypeScript",
	"typescript": "TypeScript",
	"tsx":        "TypeScript",
	"go":         "Go",
	"golang":     "Go",
	"rs":         "Rust",
	"rust":       "Rust",
	"java":       "Java",
	"kotlin":     "Kotlin",
	"kt":         "Kotlin",
	"cs":         "C#",
	"csharp":     "C#",
	"cpp":        "C++",
	"c++":        "C++",
	"c":          "C",
	"ruby":       "Ruby",
	"rb":         "Ruby",
	"php":        "PHP",
	"swift":      "Swift",
	"sql":        "SQL",
	"yaml":       "YAML",
	"yml":        "YAML",
	"json":       "JSON",
	"sh":         "Shell",
	"bash":       "Shell",
	"powershell": "PowerShell",
	"ps1":        "PowerShell",
	"dockerfile": "Dockerfile",
	"scala":      "Scala",
}

var extensionLanguageMap = map[string]string{
	"py":         "Python",
	"js":         "JavaScript",
	"jsx":        "JavaScript",
	"ts":         "TypeScript",
	"tsx":        "TypeScript",
	"go":         "Go",
	"rs":         "Rust",
	"java":       "Java",
	"kt":         "Kotlin",
	"kts":        "Kotlin",
	"cs":         "C#",
	"cpp":        "C++",
	"cc":         "C++",
	"cxx":        "C++",
	"c":          "C",
	"h":          "C/C++",
	"hpp":        "C++",
	"rb":         "Ruby",
	"php":        "PHP",
	"swift":      "Swift",
	"sql":        "SQL",
	"yaml":       "YAML",
	"yml":        "YAML",
	"json":       "JSON",
	"toml":       "TOML",
	"sh":         "Shell",
	"bash":       "Shell",
	"ps1":        "PowerShell",
	"dockerfile": "Dockerfile",
	"gradle":     "Gradle",
	"scala":      "Scala",
}

var keywordSignals = []struct {
	language string
	terms    []string
}{
	{"Python", []string{"fastapi", "django", "pytest", "poetry", "def ", "import pandas"}},
	{"JavaScript", []string{"node.js", "express", "npm", "package.json", "function(", "console.log"}},
	{"TypeScript", []string{"typescript", "tsconfig", "interface ", "type ", "nestjs"}},
	{"Java", []string{"spring boot", "maven", "pom.xml", "public class", "junit"}},
	{"Go", []string{"golang", "go.mod", "func ", "package main", "goroutine"}},
	{"Rust", []string{"cargo.toml", "fn main", "borrow checker", "rust"}},
	{"SQL", []string{"select ", "insert into", "postgres", "sqlite", "mysql"}},
	{"Dockerfile", []string{"dockerfile", "docker compose", "from alpine", "from ubuntu"}},
	{"Kotlin", []string{"kotlin", "gradle.kts", "fun main"}},
	{"C#", []string{".csproj", "asp.net", "namespace ", "using system"}},
	{"PHP", []string{"laravel", "<?php", "composer.json"}},
}

func InferLanguages(texts []string) []LanguageSignal {
	scores := map[string]LanguageSignal{}
	for _, text := range texts {
		for _, match := range codeFenceRE.FindAllStringSubmatch(text, -1) {
			lang := canonicalLanguage(match[1])
			if lang != "" {
				addSignal(scores, lang, 0.95, "code fence: "+strings.ToLower(match[1]))
			}
		}

		for _, match := range filenameRE.FindAllStringSubmatch(text, -1) {
			lang := extensionLanguageMap[strings.ToLower(match[1])]
			if lang != "" {
				addSignal(scores, lang, 0.9, "file extension: ."+strings.ToLower(match[1]))
			}
		}

		lower := strings.ToLower(text)
		for _, signal := range keywordSignals {
			for _, term := range signal.terms {
				if strings.Contains(lower, strings.ToLower(term)) {
					addSignal(scores, signal.language, 0.65, "keyword: "+term)
				}
			}
		}
	}

	result := make([]LanguageSignal, 0, len(scores))
	for _, signal := range scores {
		result = append(result, signal)
	}
	sort.Slice(result, func(i, j int) bool {
		if result[i].Confidence == result[j].Confidence {
			return result[i].Language < result[j].Language
		}
		return result[i].Confidence > result[j].Confidence
	})
	if len(result) > 5 {
		result = result[:5]
	}
	return result
}

func canonicalLanguage(raw string) string {
	lang := strings.ToLower(strings.TrimSpace(raw))
	if lang == "" {
		return ""
	}
	return fenceLanguageMap[lang]
}

func addSignal(scores map[string]LanguageSignal, language string, confidence float64, evidence string) {
	current, ok := scores[language]
	if !ok || confidence > current.Confidence {
		scores[language] = LanguageSignal{Language: language, Confidence: confidence, Evidence: evidence}
		return
	}
	if ok && current.Evidence != evidence && !strings.Contains(current.Evidence, evidence) {
		current.Evidence += "; " + evidence
		scores[language] = current
	}
}
package audit

import "testing"

func TestInferLanguagesUsesStrongSignals(t *testing.T) {
	signals := InferLanguages([]string{
		"Please refactor main.go and this snippet:\n```go\npackage main\nfunc main() {}\n```",
		"Also check package.json and the React component.",
	})

	if len(signals) == 0 {
		t.Fatal("expected language signals")
	}
	if signals[0].Language != "Go" {
		t.Fatalf("expected Go to win from code fence, got %#v", signals)
	}
	if signals[0].Confidence < 0.9 {
		t.Fatalf("expected high confidence, got %#v", signals[0])
	}
}
package proxy

import (
	"net/http"
	"strings"
	"testing"

	"vibe-coders/internal/config"
	"vibe-coders/internal/store"
)

// Reusing the routing pass's prompts for the audit record.
//
// stepRouting scores the request and audits it a few lines later, and both used to
// extract and redact the same body. The plan now carries what it extracted and the audit
// reuses it, which is only sound under two conditions — both of them easy to break later
// and neither visible at the call site.

// The model can be rewritten between the two, so it must be re-read from the current
// body rather than taken from the reused set. Getting this wrong records the model the
// client asked for instead of the one the request was actually sent as.
func TestReusedPromptsStillRecordTheRewrittenModel(t *testing.T) {
	s := &Server{cfg: testConfig("http://x.invalid", "k")}
	original := []byte(`{"model":"gpt-4o","messages":[{"role":"user","content":"hello there"}]}`)
	rewritten := rewriteModelField(original, "gpt-4o-mini")
	if !strings.Contains(string(rewritten), "gpt-4o-mini") {
		t.Fatalf("the fixture did not rewrite the model: %s", rewritten)
	}

	// Prompts as the routing pass would have produced them, from the pre-rewrite body.
	_, _, pre, _ := extractAudit(original, "/v1/chat/completions", false)
	if len(pre) == 0 {
		t.Fatal("no prompts extracted; the fixture proves nothing")
	}

	req, err := http.NewRequest(http.MethodPost, "http://gw/v1/chat/completions", nil)
	if err != nil {
		t.Fatal(err)
	}
	rec := s.auditRequestWithPrompts("/v1/chat/completions", rewritten, "k", "t", req, pre)

	if rec.Request.Model != "gpt-4o-mini" {
		t.Errorf("the audit recorded model %q; the body was rewritten to gpt-4o-mini before "+
			"it was audited, and reusing the routing pass must not carry the old name over",
			rec.Request.Model)
	}
	if len(rec.Prompts) != len(pre) {
		t.Errorf("reused prompts did not reach the record: %d vs %d", len(rec.Prompts), len(pre))
	}
}

// Raw prompt storage changes what extraction produces, so a set extracted without it
// must not be reused when it is on — the record would be missing the raw text it exists
// to keep.
func TestRawPromptStorageIgnoresTheReusedPrompts(t *testing.T) {
	cfg := testConfig("http://x.invalid", "k")
	cfg.Logging.RawPrompts = true
	s := &Server{cfg: cfg}

	body := []byte(`{"model":"m","messages":[{"role":"user","content":"remember this sentence"}]}`)
	_, _, pre, _ := extractAudit(body, "/v1/chat/completions", false)
	if len(pre) == 0 || pre[0].ContentText != "" {
		t.Fatalf("the fixture should carry redacted-only prompts, got %+v", pre)
	}

	req, err := http.NewRequest(http.MethodPost, "http://gw/v1/chat/completions", nil)
	if err != nil {
		t.Fatal(err)
	}
	rec := s.auditRequestWithPrompts("/v1/chat/completions", body, "k", "t", req, pre)

	if len(rec.Prompts) == 0 {
		t.Fatal("no prompts recorded")
	}
	if rec.Prompts[0].ContentText == "" {
		t.Error("raw prompt storage is on but the record has no raw text: the reused prompts " +
			"were extracted with it off and should have been discarded rather than reused")
	}
}

// And with nothing to reuse, the record is unchanged — the plain path still works.
func TestAuditWithoutReusedPromptsIsUnchanged(t *testing.T) {
	s := &Server{cfg: testConfig("http://x.invalid", "k")}
	body := []byte(`{"model":"m","stream":true,"messages":[{"role":"user","content":"hi"}]}`)
	req, err := http.NewRequest(http.MethodPost, "http://gw/v1/chat/completions", nil)
	if err != nil {
		t.Fatal(err)
	}

	fresh := s.auditRequest("/v1/chat/completions", body, "k", "t", req)
	_, _, pre, _ := extractAudit(body, "/v1/chat/completions", false)
	reused := s.auditRequestWithPrompts("/v1/chat/completions", body, "k", "t", req, pre)

	if fresh.Request.Model != reused.Request.Model || fresh.Request.Stream != reused.Request.Stream {
		t.Errorf("reuse changed the record: fresh model=%q stream=%v, reused model=%q stream=%v",
			fresh.Request.Model, fresh.Request.Stream, reused.Request.Model, reused.Request.Stream)
	}
	if len(fresh.Prompts) != len(reused.Prompts) {
		t.Errorf("reuse changed the prompt count: %d vs %d", len(fresh.Prompts), len(reused.Prompts))
	}
	if len(fresh.Languages) != len(reused.Languages) {
		t.Errorf("reuse changed the language signals: %d vs %d", len(fresh.Languages), len(reused.Languages))
	}
}

var _ = config.Config{}
var _ = store.PromptLog{}
