package proxy

import (
	"context"
	"io"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"vibe-coders/internal/store"
)

func TestChatCompletionAsyncAuditPreservesLanguageEvidence(t *testing.T) {
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/v1/chat/completions" {
			t.Errorf("unexpected upstream path %s", r.URL.Path)
		}
		w.Header().Set("Content-Type", "text/event-stream")
		_, _ = io.WriteString(w, "data: {\"choices\":[{\"delta\":{\"content\":\"ok\"},\"finish_reason\":\"stop\"}],\"usage\":{\"prompt_tokens\":7,\"completion_tokens\":1,\"total_tokens\":8}}\n\ndata: [DONE]\n\n")
	}))
	defer upstream.Close()

	db := openTestStore(t)
	defer db.Close()
	logger := store.NewAsyncLogger(db, 32, filepath.Join(t.TempDir(), "fallback.ndjson"))
	logger.Start()
	defer logger.Stop(context.Background())
	server, err := NewServer(testConfig(upstream.URL, "test-key"), db, logger, nil)
	if err != nil {
		t.Fatal(err)
	}
	proxy := httptest.NewServer(server.Routes())
	defer proxy.Close()

	response := postJSON(t, proxy.URL+"/v1/chat/completions", "", map[string]any{
		"model": "test-model", "stream": true,
		"messages": []map[string]string{
			{"role": "user", "content": "pytest"},
			{"role": "user", "content": "worker.py"},
			{"role": "user", "content": "```python\npass\n```"},
		},
	})
	defer response.Body.Close()
	body, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatal(err)
	}
	if response.StatusCode != http.StatusOK || !strings.Contains(string(body), "data: [DONE]") {
		t.Fatalf("unexpected proxy response: status=%d body=%s", response.StatusCode, body)
	}

	var requestID string
	waitFor(t, 3*time.Second, func() bool {
		recent, err := db.RecentRequests(context.Background(), store.RequestFilter{Limit: 1})
		if err != nil || len(recent) != 1 {
			return false
		}
		requestID = recent[0].ID
		return true
	})
	detail, err := db.RequestDetail(context.Background(), requestID)
	if err != nil {
		t.Fatal(err)
	}
	if len(detail.Prompts) != 3 {
		t.Fatalf("expected three stored prompts, got %d", len(detail.Prompts))
	}
	assertPythonLanguageEvidence(t, detail.Languages)
}
